// The query executed by ChatMessages.
const ChatMessages_Operation = `
query ChatMessages ($filter: NodeFilter, $limit: Int, $offset: Int) {
	findNodes(filter: $filter, sort: seq, limit: $limit, offset: $offset) {
		hits {
			node {
				loc
				seq
				content
				data
			}
		}
	}
}
`

// Team-chat reads (hadron chat read). Messages are chat-message nodes under a
// `messagesLoc` prefix — canonical shape (D-2026-08-07-001/-004): the body in
// `content`, the envelope (author/timestamp/…) in `data`. `content` AND `data`
// are selected so one findNodes call returns everything, and so the legacy
// academy dialect (body in data.body, `message` nodeType) still reads — accept
// everything, emit canonical. sort: seq gives server-assigned order; the CLI
// paginates to exhaustion and filters seq>since client-side (there is no
// server-side seq cursor).
//
// NodeFilter is a SHARED generated struct, and genqlient resolves a shared input
// type's field-level omitempty per-operation with last-writer-wins (not a merge).
// So this op must repeat FindNodes' (nodes.graphql) FULL set verbatim — a partial
// or empty set here would non-deterministically strip omitempty off the struct
// depending on generation order. Keep these two lists identical.
func ChatMessages(
	ctx_ context.Context,
	client_ graphql.Client,
	filter *NodeFilter,
	limit *int,
	offset *int,
) (data_ *ChatMessagesResponse, err_ error) {
	req_ := &graphql.Request{
		OpName: "ChatMessages",
		Query:  ChatMessages_Operation,
		Variables: &__ChatMessagesInput{
			Filter: filter,
			Limit:  limit,
			Offset: offset,
		},
	}

	data_ = &ChatMessagesResponse{}
	resp_ := &graphql.Response{Data: data_}

	err_ = client_.MakeRequest(
		ctx_,
		req_,
		resp_,
	)

	return data_, err_
}

